mapper.select:
SELECT MATERIAL_ID FROM BOARD_MATERIAL
 WHERE BID_CASE_ID = #{bidCaseId} AND BOARD_YEAR = #{year}
 ORDER BY MATERIAL_ID FOR UPDATE

SELECT , 
  FROM BOARD_MATERIAL m 
 WHERE m.MATERIAL_ID = #{id}

SELECT , 
  FROM BOARD_MATERIAL m 


    m.BID_CASE_ID IN (SELECT a.BID_CASE_ID FROM BID_ASSIGNMENT a WHERE a.EMP_NO = #{empNo} AND a.ACTIVE_YN = 1)


    AND i.NAME_KO LIKE CONCAT(CONCAT('%', #{q}), '%') ESCAPE '!'


    AND m.STATUS_CD = #{status}


    AND m.BOARD_YEAR = #{year}


    AND m.MEETING_DATE >= #{meetingFrom}


    AND m.MEETING_DATE <= #{meetingTo}


    AND EXISTS (SELECT 1 FROM BID_ASSIGNMENT a2 JOIN USERS u2 ON u2.EMP_NO = a2.EMP_NO
                 WHERE a2.BID_CASE_ID = m.BID_CASE_ID AND a2.ACTIVE_YN = 1
                   AND u2.NAME LIKE CONCAT(CONCAT('%', #{assignee}), '%') ESCAPE '!')


 ORDER BY m.UPDATED_AT DESC, m.MATERIAL_ID DESC

mapper.update:
UPDATE BOARD_MATERIAL SET CUR_SNAP = #{next}, LAST_SAVED_BY = #{by}, LAST_SAVED_AT = #{now},
       UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE MATERIAL_ID = #{id} AND CUR_SNAP = #{base} AND STATUS_CD IN ('PREP', 'DRAFT')

UPDATE BOARD_MATERIAL SET STATUS_CD = 'SUBMITTED', SUBMIT_REQ_ID = #{reqId}, SUBMIT_SNAP = #{snap},
       UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE MATERIAL_ID = #{id} AND STATUS_CD = 'DRAFT' AND CUR_SNAP = #{snap}

UPDATE BOARD_MATERIAL SET STATUS_CD = 'CONFIRMED', CONFIRMED_SNAP = SUBMIT_SNAP, CONFIRMED_BY = #{by},
       CONFIRMED_AT = #{now}, SUBMIT_REQ_ID = NULL, SUBMIT_SNAP = NULL, UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE MATERIAL_ID = #{id} AND STATUS_CD = 'SUBMITTED' AND SUBMIT_REQ_ID = #{reqId}

UPDATE BOARD_MATERIAL SET STATUS_CD = 'DRAFT', SUBMIT_REQ_ID = NULL, SUBMIT_SNAP = NULL,
       UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE MATERIAL_ID = #{id} AND STATUS_CD = 'SUBMITTED' AND SUBMIT_REQ_ID = #{reqId}

UPDATE BOARD_MATERIAL SET STATUS_CD = 'DRAFT', RESULT_CD = NULL, MEETING_DATE = NULL, CONFIRMED_SNAP = NULL,
       CONFIRMED_BY = NULL, CONFIRMED_AT = NULL, UPDATED_BY = #{by}, UPDATED_AT = #{now}
 WHERE MATERIAL_ID = #{id} AND STATUS_CD = 'CONFIRMED'

