SELECT s.MATERIAL_ID, s.SNAP_NO, s.VALUES_JSON, s.NOTE, s.SAVED_BY, u.NAME AS SAVED_BY_NAME, s.SAVED_AT
  FROM BOARD_MATERIAL_SNAP s LEFT JOIN USERS u ON u.EMP_NO = s.SAVED_BY
 WHERE s.MATERIAL_ID = #{id} AND s.SNAP_NO = #{snapNo}
